import {frenchLessons} from './french-content.mjs';
import {orderEditor,orderResult} from './story-order-ui.mjs';
import {parisDestinations,parisStories} from './paris-library.mjs';
import {parisPlan} from './paris-core.mjs';
import {hearButton} from './play-media.mjs';
import {helpers,acceptsAnswer} from './help-content.mjs';
import {guides,avatars,portrait,gardenScene} from './companions.mjs';
import {entrances,storyNodes} from './story-content.mjs';
import {ensureGarden,currentVisit,entranceById,storyDescribe} from './garden-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heading=(title,body)=>`<div class="page-heading"><a href="#home" class="back">← Back to the garden</a><h1>${esc(title)}</h1><p>${esc(body)}</p></div>`;
const named=(s,g)=>esc(s.replaceAll('{guide}',g.name));
const guideOf=s=>guides.find(g=>g.id===s.garden.guide);
export function companionLink(state){const g=guideOf(state);return `${portrait(g.id,true)}<span>With ${g.name}</span>`;}
export function guideRail(state,line){const g=guideOf(state);return `<aside class="guide-rail"><div class="guide-face">${portrait(g.id)}</div><h2>${g.name}</h2><p>${line?named(line,g):esc(g.hello)}</p><a href="#companions">Change companions</a><p class="tiny">Read, draw, talk, or take a break. You can find your own way.</p></aside>`;}
const visitTitle=v=>v.paris?parisStories.find(s=>s.id===v.paris.storyId)?.title||entranceById(v.entrance).title:entranceById(v.entrance).title;
const pathIcon=id=>({creature:'✧',message:'✉',shelter:'⌂',cafe:'♧',paris:'✈'}[id]|| (id.startsWith('french-')?'✈':'✧'));
export function gardenHome(state,persist){
 const g=ensureGarden(state),v=currentVisit(state);
 return `<section class="garden-opening"><div class="garden-introduction"><p class="place-name">First morning in the Learning Garden</p><h1>The storm has passed.<br>The garden needs a hand.</h1><p>All our neighbors are safe. But the wind has scattered supplies, little hideaways need new ideas, and hungry visitors are arriving at the café.</p><p>Will you help us make the garden welcoming again? Gather curious foods, feed a neighbor, follow a message, or imagine a cozy shelter. Your guide will come with you.</p>${hearButton('The storm has passed. All our neighbors are safe. But the wind has scattered supplies, little hideaways need new ideas, and hungry visitors are arriving at the café. Will you help us make the garden welcoming again? Gather curious foods, feed a neighbor, follow a message, or imagine a cozy shelter. Your guide will come with you. Choose one small thing to try. There is no hurry, and you can ask for help or take a break.','Hear how our story begins')}<div class="hero-actions"><a class="primary" href="#cafe">Feed a hungry neighbor</a><a class="secondary" href="#storm">Find another way to help</a><a class="text-button" href="#companions">Choose your companions</a></div><p class="tiny">Choose one small thing. There is no hurry, and help is always welcome.</p><p class="tiny">${persist?'Your place is remembered in this browser.':'Saving is off. Your place lasts while this page stays open.'}</p></div><div class="garden-map">${gardenScene()}<button type="button" class="map-sign sign-creature" data-start-path="creature"><span>${pathIcon('creature')}</span>Follow a creature</button><button type="button" class="map-sign sign-message" data-start-path="message"><span>${pathIcon('message')}</span>Investigate a note</button><button type="button" class="map-sign sign-shelter" data-start-path="shelter"><span>${pathIcon('shelter')}</span>Make a hideaway</button></div></section><section class="welcome-companion"><div>${portrait(g.guide)}</div><blockquote><p>“${esc(guideOf(state).hello)}”</p><footer>${guideOf(state).name}, your companion <a href="#companions">Change</a></footer></blockquote><div class="explorer-stamp">${portrait(g.avatar,true)}<span>Your explorer</span></div></section>${v?`<div class="resume-strip"><span>${v.finished?'An idea is waiting to go with you.':`Your visit is waiting: ${esc(visitTitle(v))}.`}</span><a class="secondary" href="#storm/${v.finished?'end':'play'}">${v.finished?'See your ending':'Continue our visit'}</a></div>`:''}<section class="paris-invitation"><img src="./paris-scene.svg" alt="An imagined Paris skyline, with the Eiffel Tower and a bridge over the Seine" width="800" height="450"><div><p class="place-name">A journey beyond the garden</p><h2>A postcard from Paris.</h2><p>A bookseller has stories to send our neighbors. Follow a note, become a word detective, and help a parcel find its way home.</p><a class="primary" href="#paris">Visit Paris together</a></div></section><section class="science-gate"><svg viewBox="0 0 160 160" aria-hidden="true"><path d="M80 12Q20 80 24 110Q28 150 80 150Q132 150 136 110Q140 80 80 12Z" fill="#abc4da"/><path d="M44 111Q80 82 116 111M48 126Q80 103 112 126" fill="none" stroke="#fffef9" stroke-width="5"/><circle cx="80" cy="59" r="10" fill="#fffef9"/></svg><div><h2>Puddles, frost, and a good question.</h2><p>The storm left water all around the garden. Before we make plans, let’s look closely: what happens when ice melts, and where does a puddle go? Explore with your guide and tell someone what you notice.</p><a class="primary" href="#science">Explore water together</a></div></section><section class="cafe-invitation"><div class="cafe-sketch" aria-hidden="true">☾<span>ALMOST-RIGHT CAFÉ</span>♧</div><div><p class="place-name">A warm welcome after the storm</p><h2>Let’s get the café cooking.</h2><p>Our hungry neighbors fancy dishes we haven’t got. Luckily, the cupboard holds some wonderfully odd alternatives. Find what each guest likes, make a plate, and head to the orchard when a jar runs low.</p><a class="primary" href="#cafe">Open the Almost-Right Café</a></div></section><section class="number-destination"><div class="number-emblem" aria-hidden="true">+ × ÷<br><span>✿</span></div><div><h2>Number Garden is still growing.</h2><p>Visit the seven math patches for check-ins, multiplication, picture playgrounds, and things to wonder about.</p><a class="primary" href="#facts">Explore all facts through 12 × 12</a><a class="secondary" href="#numbers">Explore Number Garden</a></div></section><p class="tiny garden-note">Explore together. Every path is open. No timer, grades, or need to finish everything.</p>`;
}
const parisLengths={1:'A little text',2:'A little more',3:'A longer passage'};
function parisSketch(id){
 const art={
 bookstall:'<path d="M24 44H176V126H24Z" fill="#e9b84a"/><path d="M16 44L32 18H168L184 44Z" fill="#ce777d"/><path d="M24 44H176M36 73H164M36 103H164"/><path d="M42 58V73M55 56V73M72 60V73M87 54V73M110 57V73M128 54V73M143 60V73M47 84V103M68 81V103M82 84V103M108 82V103M124 86V103M145 81V103"/><path d="M20 130H180"/>',
 river:'<path d="M8 97Q50 80 94 99T192 97V140H8Z" fill="#abc4da" stroke="none"/><path d="M14 94V63H186V94M14 63H186M18 84Q52 40 85 84M115 84Q149 40 182 84"/><path d="M30 113Q56 103 80 113M109 125Q135 115 161 125"/><path d="M131 37H161L151 49H141Z" fill="#e9b84a"/><path d="M145 13V37M145 13L163 31H145" fill="#fffdf4"/>',
 rooftops:'<path d="M19 137V81H181V137" fill="#c9dcd2"/><path d="M9 81L54 40H150L191 81Z" fill="#abc4da"/><path d="M48 91H78L72 116H54Z M112 91H148L141 116H120Z" fill="#ce777d"/><path d="M63 91V56M130 91V55"/><path d="M63 73Q40 68 45 55Q67 53 63 73M63 65Q82 61 83 47Q62 44 63 65M130 72Q110 70 111 55Q133 51 130 72M130 64Q150 60 153 43Q129 43 130 64" fill="#86b4a4"/>'
 };
 return `<svg class="paris-destination-art" viewBox="0 0 200 150" aria-hidden="true" fill="none" stroke="#274e48" stroke-width="3" stroke-linejoin="round" stroke-linecap="round">${art[id]||''}</svg>`;
}
function packInvitations(state){
 return parisStories.filter(story=>story.packId).map(story=>{
  const plan=parisPlan(state,story.destination,'auto',story.id);
  return `<section class="paris-pack-invitation"><svg viewBox="0 0 180 160" aria-hidden="true"><rect x="18" y="24" width="144" height="116" rx="6" fill="#abc4da"/><path d="M18 24H162V61Q144 71 130 50V132H50V50Q36 72 18 61Z" fill="#ce777d"/><path d="M70 65Q84 81 97 65Q82 101 70 65Z" fill="#e9b84a"/><path d="M82 124L87 103L99 109L104 100L112 120L106 132H88Z" fill="#b97d51"/><path d="M88 129L66 121Q67 138 89 137" fill="#b97d51"/><circle cx="104" cy="118" r="2" fill="#183f39"/><path d="M14 142H166" stroke="#183f39" stroke-width="4"/></svg><div><p class="place-name">Another Paris story</p><h2>${esc(story.title)}</h2><p>${esc(story.invitation||'A new little errand is waiting. Read a story and find your way together.')}</p><label for="paris-pack-length-${story.id}">How much text for this story?</label><select id="paris-pack-length-${story.id}"><option value="auto">Suggested: ${{1:'short',2:'medium',3:'longer'}[plan.variant]}</option>${[1,2,3].map(n=>`<option value="${n}">${parisLengths[n]}</option>`).join('')}</select><button class="primary" data-paris-pack-story="${story.id}" data-paris-pack-place="${story.destination}">Visit this story</button></div></section>`;
 }).join('');
}
function storyConnections(visit){
 const story=visit.paris&&parisStories.find(s=>s.id===visit.paris.storyId);
 return story?.connections?.length?`<details class="reading-connections"><summary>Grown-ups: learning connections</summary>${story.connections.map(c=>`<p><strong>${esc(c.label)}</strong>: ${esc(c.scope)} <a href="https://github.com/withmarbleapp/os-taxonomy/blob/96a7933754af672e1bfdbf7ecb05c325860c6e0d/data/topics.json" target="_blank" rel="noopener">Marble topic ${esc(c.topicId)}</a>.</p>`).join('')}<p class="tiny">A connection describes part of this practice; it does not establish mastery of the topic.</p></details>`:'';
}
export function parisLanding(state){
 const v=currentVisit(state),g=state.garden;
 const destinationCards=parisDestinations.map(place=>{
  const plan=parisPlan(state,place.id),story=parisStories.find(x=>x.id===plan.storyId);
  const seen=g.seen.some(id=>storyNodes[id]?.parisStory===plan.storyId);
  return `<article class="paris-destination">${parisSketch(place.id)}<h2>${esc(place.title)}</h2><p>${esc(place.description)}</p><p class="paris-next-story">${seen?'A story to revisit':'A story waiting'}: <strong>${esc(story?.title||'An errand with Lucie')}</strong></p><label for="paris-length-${place.id}">How much text today?</label><select id="paris-length-${place.id}"><option value="auto">Suggested: ${{1:'short',2:'medium',3:'longer'}[plan.variant]}</option>${[1,2,3].map(n=>`<option value="${n}">${parisLengths[n]}</option>`).join('')}</select><button type="button" class="primary" data-paris-destination="${place.id}">Explore ${esc(place.title.replace(/^The /,'the '))}</button><details><summary>Grown-ups: why this suggestion?</summary><p>${esc(plan.reason)}</p><p>All passage lengths stay open. Two questions share a passage; the second is rereading practice.</p></details></article>`;
 }).join('');
 return `${heading('Paris is waiting.','Choose a little errand. There are stories beside the river, among the books, and above the rooftops.')}<section class="paris-exploration-intro"><img src="./paris-scene.svg" alt="An imagined Paris scene with rooftops, the Eiffel Tower, and a bridge over the Seine" width="800" height="450"><div><p class="place-name">The Paris Postcard</p><h2>Where shall we wander?</h2><p>Lucie and her neighbors have stories to share with the Learning Garden. Read a little, follow a clue, and help along the way. This is a make-believe visit to real Paris, France. These stories are in English.</p><a class="secondary" href="#french">Explore Paris en français</a>${hearButton('Where shall we wander? Choose Lucie’s bookstall, the river walk, or the rooftop garden. Each errand has a little story and two questions. You can listen, read together, ask for help, or take a break.','Hear our Paris invitation')}${v?.entrance==='paris'&&!v.finished?`<button class="secondary" data-resume-visit="${v.id}">Continue our waiting Paris visit</button>`:''}<p class="tiny">Two questions, then an optional postcard. No hurry.</p></div></section>${packInvitations(state)}<section class="paris-destinations" aria-label="Places to explore in Paris">${destinationCards}</section><section class="paris-original"><h2>The first postcard</h2><p>Follow Lucie’s original six-stop parcel errand, or return to its familiar pages.</p><button class="secondary" data-start-path="paris">${v?.entrance==='paris'&&!v.paris&&!v.finished?'Continue our Paris visit':'Begin our Paris visit'}</button></section><details class="paris-parent-note"><summary>Grown-ups: reading and returning</summary><p>${parisStories.length} original stories each have two questions, available at three authored passage lengths. They cover detail, word parts, vocabulary, inference, evidence, and sequence. The next errand favors a less encountered story at the chosen place. Once a place’s stories are familiar, it offers rereading; new stories are not generated.</p><p>Suggestions use recent work at each place. Support or retries can suggest shorter text; two independent first tries on different new stories can suggest longer text. Skips and unobserved reading do not count as failure. Listening, sentence highlighting, reading together, and smaller examples are always welcome and stay recorded separately. These are approximate practice suggestions, not a reading level, decoding test, fluency measure, or placement decision. Manual length choices stay open.</p><p>The notes and suggestions stay in this browser and follow the existing saving, export, and reset controls. Design references: <a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/21/Published" target="_blank" rel="noopener">IES foundational reading skills</a> and <a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/14" target="_blank" rel="noopener">reading comprehension</a>. The story people and errands are invented.</p></details>`;
}
export function companionPicker(state){
 const g=ensureGarden(state);
 return `${heading('Who’s coming with you?','Choose a guide and an explorer. You can change either whenever you like. No name or profile is needed.')}<section class="companion-section"><h2>Your guide</h2><p class="tiny">Every guide explores every path with you.</p><div class="companion-options">${guides.map(x=>`<button class="companion-option ${g.guide===x.id?'selected':''}" data-guide="${x.id}" aria-pressed="${g.guide===x.id}">${portrait(x.id)}<strong>${x.name}</strong><span class="tiny">${x.pronouns}</span><span>${esc(x.description)}</span><span class="choice-tick">${g.guide===x.id?'✓ Chosen':'Choose '+x.name}</span></button>`).join('')}</div></section><section class="companion-section"><h2>Your explorer</h2><p class="tiny">Choose the character you would like to be. This choice is separate from your guide.</p><div class="companion-options">${avatars.map(x=>`<button class="companion-option explorer-option ${g.avatar===x.id?'selected':''}" data-avatar="${x.id}" aria-pressed="${g.avatar===x.id}">${portrait(x.id)}<strong>${x.name}</strong><span>${x.description}</span><span class="choice-tick">${g.avatar===x.id?'✓ Chosen':'Choose this explorer'}</span></button>`).join('')}</div></section><div class="summary-links"><a class="primary" href="#storm">Explore the first morning</a><a class="secondary" href="#home">Back to the garden</a></div>`;
}
export function storyHub(state,pending,parisOptions=null){
 const v=currentVisit(state),g=state.garden,want=entranceById(pending);
 const confirmation=want&&v&&!v.finished?`<section class="visit-decision" role="region" aria-label="A visit is waiting"><h2>You have a visit waiting.</h2><p>You were exploring “${esc(visitTitle(v))}.” You can continue, or begin “${esc(want.title)}” and keep the earlier visit here.${parisOptions?` Your new errand will explore ${esc(parisOptions.storyId?parisStories.find(x=>x.id===parisOptions.storyId)?.title||"Paris":parisDestinations.find(x=>x.id===parisOptions.destination)?.title||"Paris")}.`:""}</p><div class="summary-links"><button class="primary" data-resume-visit="${v.id}">Continue the waiting visit</button><button class="secondary" data-new-visit="${want.id}" ${parisOptions?`data-paris-place="${esc(parisOptions.destination)}" data-paris-variant="${esc(parisOptions.variant)}" ${parisOptions.storyId?`data-paris-story="${esc(parisOptions.storyId)}"`:""}`:""}>Begin this new path</button></div></section>`:'';
 return `${heading('Choose a small way to help','After the storm, every good idea can make the garden a little more welcoming. Follow a neighbor’s tracks, read a message, imagine a shelter, open the café, or follow a reading errand in Paris. Each path is a whole visit; you can stop whenever you like.')}${confirmation}<div class="story-paths">${entrances.map(e=>`<article class="story-path path-${e.id}"><div class="path-sketch" aria-hidden="true">${pathIcon(e.id)}</div><h2${e.language==='fr'?' lang="fr"':''}>${esc(e.title)}</h2><p>${esc(e.invitation)}</p>${e.id==='paris'?'<a class="secondary" href="#paris">Explore Paris stories</a>':''}<button class="primary" data-start-path="${e.id}">${v&&!v.finished&&v.entrance===e.id&&!(e.id==='paris'&&v.paris)?'Continue this path':g.visits.some(x=>x.entrance===e.id&&x.finished)?'Visit this path again':'Start here'}</button></article>`).join('')}</div>${g.visits.length?`<section class="visit-notebook"><h2>Your visits</h2><p class="tiny">Earlier visits stay here when you choose another entrance.</p><ul>${[...g.visits].reverse().map(x=>`<li><div><strong>${esc(visitTitle(x))}</strong><span class="tiny">Visit ${x.id.split('-').at(-1)} · ${x.finished?'At an ending':'A place to return to'}</span></div><button class="secondary" data-resume-visit="${x.id}">${x.finished?'See the ending':'Continue'}</button></li>`).join('')}</ul></section>`:''}<a class="text-button" href="#numbers">Visit Number Garden instead</a>`;
}
function storyPicture(n){
 if(n.visual==='array')return `<div class="story-diagram"><div class="model-array" style="grid-template-columns:repeat(${n.diagram.cols},1fr)" role="img" aria-label="${n.diagram.rows} rows of ${n.diagram.cols} stones">${'<span></span>'.repeat(n.diagram.rows*n.diagram.cols)}</div></div>`;
 if(n.visual==='ruler'){
  const d=n.diagram,x=i=>24+i/d.max*360;
  return `<div class="story-diagram"><svg viewBox="0 0 410 105" role="img" aria-label="A ruler in centimetres, with a ribbon from ${d.start} to ${d.end}"><rect x="${x(d.start)}" y="15" width="${x(d.end)-x(d.start)}" height="24" rx="3" fill="#da8d8d"/><path d="M24 60H384" stroke="#183f39" stroke-width="2"/>${Array.from({length:d.max+1},(_,i)=>`<path d="M${x(i)} 55v12" stroke="#183f39"/><text x="${x(i)}" y="88" text-anchor="middle" font-size="14" fill="#183430">${i}</text>`).join('')}</svg></div>`;
 }
 return '';
}
const readingLabels=[['unobserved','Reading not observed'],['together','We read it together'],['listened','We listened to the passage'],['independent','I read it independently']];
function readingPassage(n,d){
 if(!n.readingText)return '';
 const tools=d.readingTools||{},index=tools.focus;
 const focusLabel={'paris-note':'Find a detail','paris-reread':'Look inside a word','paris-narrow':'Use nearby clues','paris-infer':'Connect two clues','paris-evidence':'Point to the words','paris-sequence':'Put events in order'}[n.id]||n.readingSkill;
 const responseText=n.kind==='order'?['Cards to put in order.',...n.displayOrder.map(i=>n.orderItems[i])]:n.choices.map((c,i)=>n.language==='fr'?c:`Choice ${i+1}. ${c}`);
 const spoken=[...n.readingText,n.prompt,...responseText].join(' ');
 return `<section class="reading-passage" aria-labelledby="reading-passage-title"><div class="reading-passage-heading"><h3 id="reading-passage-title">From our Paris notebook</h3><span>${esc(focusLabel)}</span></div><p class="connected-text"${n.language==='fr'?' lang="fr"':''}>${n.readingText.map((line,i)=>`<span class="reading-line ${index===i?'sentence-current':''}" id="reading-line-${i}" tabindex="-1" ${index===i?'aria-current="true"':''}>${esc(line)}</span>`).join(' ')}</p><div class="reading-tool-buttons"><button type="button" class="secondary" data-story-reading-tool="sentence-next" ${index===n.readingText.length-1?'disabled':''}>${index===null||index===undefined?'Follow one sentence':'Next sentence'}</button>${index!==null&&index!==undefined?'<button type="button" class="text-button" data-story-reading-tool="whole">Read without highlighting</button>':''}${hearButton(spoken,n.language==='fr'?'Écouter le passage et la question':'Hear passage and question',n.language||'en').replace('data-speak=', 'data-story-audio data-speak=')}</div><p class="tiny" id="reading-support-note">${tools.audioRequested?'You can listen, pause, and read the passage again.':tools.sentenceUsed?'The whole passage stays here while we follow one sentence at a time.':'Read silently, read together, or listen. You can return to any sentence.'}</p></section>`;
}
export function storyPage(state,d){
 const v=currentVisit(state),n=storyNodes[v.node],correct=acceptsAnswer(n,d.attempts.at(-1)),project=n.type==='project';
 const choices=project?(n.projectOptions||{creature:['A winding trail','A short trail','My own route'],message:['A picture','Words told to a helper','A picture and words'],shelter:['A tall doorway','A wide roof','My own shape']}[n.entrance]):null;
 return `${heading(entranceById(v.entrance).chapter||'First Morning',entranceById(v.entrance).title)}<div class="story-layout ${n.kind==='order'?'ordering-layout':''}"><article class="story-sheet"><div class="story-chapter"><span>${esc(n.subject)} ${project?'· Imagine and make':'· A little investigation'}</span><span class="travelling-explorer">${portrait(state.garden.avatar,true)}</span></div><h2>${esc(n.title)}</h2>${v.paris?`<p class="paris-errand-label">${esc(parisStories.find(s=>s.id===v.paris.storyId)?.title||'A Paris errand')} · ${parisLengths[v.paris.variant]} · ${n.type==='project'?'A postcard to imagine':`Question ${v.route.indexOf(n.id)+1} of 2`}</p>`:''}<p class="story-body"${n.language==='fr'&&!project?' lang="fr"':''}>${esc(n.body)}</p>${(n.entrance==='paris'||n.language==='fr')?'<img class="paris-story-strip" src="./paris-scene.svg" alt="A Paris skyline, showing the setting of our imaginary story" width="800" height="450">':''}${readingPassage(n,d)}${storyPicture(n)}<p class="story-question"${n.language==='fr'&&!project?' lang="fr"':''}>${esc(n.prompt)}</p>${project?`<div class="project-invitation"><p>Your design, your choice. There is no right answer.</p><div class="project-choices" role="group" aria-label="Choose an idea">${choices.map(x=>`<button type="button" class="method ${d.designChoice===x?'selected':''}" data-design="${esc(x)}" aria-pressed="${d.designChoice===x}">${esc(x)}</button>`).join('')}</div>${d.designChoice?`<p class="design-note">An idea to take with you: <strong>${esc(d.designChoice)}</strong>.</p>`:''}<p class="tiny">Choosing or continuing records an invitation, not proof that you made something. You do not need to send us your work.</p><button class="primary" id="story-project-next">Take this idea to the ending</button></div>`:`${!correct?`<form id="story-answer-form" novalidate>${n.kind==='order'?orderEditor(n,d):n.kind==='choice'?`<div class="choices story-choices" role="group" aria-label="Choose an answer">${n.choices.map((x,i)=>`<button type="button" class="choice ${d.choice===i?'selected':''}" data-story-choice="${i}"${n.language==='fr'?' lang="fr"':''} aria-pressed="${d.choice===i}">${esc(x)}</button>`).join('')}</div><button class="primary" type="submit">Try this idea</button>`:`<label for="story-answer" class="answer-label">Your answer${n.visual==='ruler'?' (centimetres)':''}</label><div class="answer-line"><input id="story-answer" type="text" inputmode="numeric" autocomplete="off" value="${esc(d.input)}" aria-describedby="story-error"><button type="submit" class="primary">Try my answer</button></div>`}<p class="tiny" id="story-error" role="alert">${esc(d.error||'')}</p></form>`:''}${correct&&n.kind==='order'?orderResult(n,d):''}<div id="story-feedback" aria-live="polite">${correct?`<p class="feedback success">${esc(n.answerFeedback?.[d.attempts.at(-1)]||'That fits. What helped you find it?')}</p>`:d.attempts.length?`<p class="feedback">${esc(n.answerFeedback?.[d.attempts.at(-1)]||'An idea worth another look. You can try again, ask for a hint, or leave this question for now.')}</p>`:''}</div><div class="helper-offer ${d.attempts.length&&!correct?'after-miss':''}"><button class="secondary" id="story-help">Try a smaller example</button><p class="tiny">Your question waits here. A picture or little example might help.</p></div><div class="support-actions">${!d.hinted?`<button class="text-button" id="story-hint">${n.language==='fr'?'English meaning & word help':'A little hint'}</button>`:''}${!d.revealed?'<button class="text-button" id="story-explain">Think it through together</button>':''}</div>${d.hinted?`<div class="hint"><strong>${n.language==='fr'?'English meaning & word help':'A little nudge'}</strong><p>${esc(n.hint)}</p></div>`:''}${d.revealed?`<div class="solution"><strong>One way to think about it</strong><p>${esc(n.explanation)}</p></div>`:''}${correct?`<fieldset class="story-method"><legend>How did you find it? Choose together.</legend><div class="method-grid">${[['knew','I knew it'],['worked','I worked it out'],['counted','I counted'],['together','We did it together']].filter(([id])=>!(n.entrance==='paris'||n.language==='fr')||id!=='counted').map(([id,label])=>`<button type="button" class="method ${d.method===id?'selected':''}" data-story-method="${id}" aria-pressed="${d.method===id}">${label}</button>`).join('')}</div></fieldset>`:''}`}
 <details class="reading-record" ${n.subject==='Reading'?'open':''}><summary>How did we read this part?</summary><p class="tiny">This is separate from solving the question. Reading together is welcome. Leave “not observed” if you did not notice.</p><div class="reading-options" role="group" aria-label="Reading observation">${readingLabels.map(([id,label])=>`<button type="button" class="method ${d.reading===id?'selected':''}" data-reading="${id}" aria-pressed="${d.reading===id}">${label}</button>`).join('')}</div></details>
 ${!project?`<div class="next-row">${correct?`<button class="primary" id="story-next" ${!d.method?'disabled':''}>Keep exploring</button>`:'<button class="text-button" id="story-skip">Leave this question for now</button>'}${n.language==='fr'?'<a class="text-button" href="#french">Back to French Paris</a>':v.paris?'<a class="text-button" href="#paris">Back to the Paris map</a>':''}<a class="text-button" href="#home">Pause in the garden</a></div>`:`${n.language==='fr'?'<a class="text-button" href="#french">Back to French Paris</a>':v.paris?'<a class="text-button" href="#paris">Back to the Paris map</a>':''}<a class="text-button" href="#home">Pause in the garden</a>`}<p class="tiny story-progress-note">${n.entrance==='paris'?(project?'Your postcard idea can wait for another day.':'This is reading practice. The passage can stay open, and you can take a break at any stop.'):'This path can finish on its own. No other path is required.'}</p>${storyConnections(v)}</article>${guideRail(state,n.guide)}<aside class="story-wonder"><h3>Something to wonder</h3><p>${esc(correct||d.revealed||project?n.talk:'What do you notice? Where would you like to start?')}</p><p class="tiny">Talk, draw, or imagine together. The app does not score your explanation.</p></aside></div>`;
}
export function storyEnding(state){
 const v=currentVisit(state);if(!v?.finished)return storyHub(state);
 const e=entranceById(v.entrance),obs=state.garden.observations.filter(o=>o.visitId===v.id),idea=Object.values(v.drafts).find(d=>d.designChoice)?.designChoice;
 return `${heading('A place to pause.','One path is a whole visit. You can stop here, take an idea with you, or follow a different curiosity.')}<div class="story-layout"><article class="story-sheet story-ending"><span class="ending-leaf" aria-hidden="true">✧</span><h2>${esc(v.paris?'A small errand, a story to share':e.ending.title)}</h2><p class="story-body">${esc(v.paris?'Your Paris errand has reached a place to pause. There is room to talk about what happened, imagine a postcard, or wander somewhere else.':e.ending.body)}</p><section class="takeaway"><h3>${esc(e.ending.projectTitle)}</h3><p>${esc(e.ending.project)}</p>${idea?`<p class="design-note">Your chosen idea: ${esc(idea)}.</p>`:''}<p class="tiny">Entirely optional. Nothing to upload, photograph, or hand in.</p></section><div class="summary-links">${e.language==='fr'?'<a class="primary" href="#french">Explore more French stories</a>':v.entrance==='paris'?'<a class="primary" href="#paris">Explore more Paris stories</a>':''}<a class="secondary" href="#home">Back to the Learning Garden</a><a class="secondary" href="#storm">Follow another curiosity</a></div><details><summary>Grown-ups: what we noticed on this visit</summary>${obs.map(storyEvidence).join('')}<a href="#notes">All grown-up notes</a></details></article>${guideRail(state,'{guide} says, “There’s always more to wonder about. This is a good place to pause.”')}</div>`;
}
function storyEvidence(o){return `<div class="evidence-item"><strong>${esc(o.title)} — ${esc(storyDescribe(o))}</strong><p>${esc(o.prompt)}</p>${o.readingSkill?`<p>${o.language==='fr'?'French practice. ':''}Reading focus: ${esc(o.readingSkill)}.${o.parisStory?` Story: ${esc(parisStories.find(s=>s.id===o.parisStory)?.title||o.parisStory)}. Passage: ${parisLengths[o.parisVariant]||"unknown length"}. ${o.priorStorySeen?"This story was encountered earlier, possibly at another length.":"This story was new at the start of this errand."} Selection: ${esc(o.parisSelectionReason||"Not recorded")}.`:""} ${o.priorPassageSeen?'This passage was encountered earlier; this is rereading practice.':'This visit introduced this passage.'}${o.readingTools?.audioRequested?' Read-aloud requested; playback was not verified.':''}${o.readingTools?.sentenceUsed?' Sentence focus used.':''}${o.readingTools?.supportUncertain?' Earlier reading support could not be determined.':''}</p>`:''}<p>${o.status==='invitation'?'Project invitation only.':`Answers tried: ${esc(o.attempts.map(v=>o.choices?.[v]??v).join(', ')||'None')}.`}${o.helpUsed?' Smaller example opened.':''}${o.hinted?(o.language==='fr'?' English meaning and word help opened.':' Hint opened.'):o.meaningUsed?' English meaning was opened earlier for this passage.':''}${o.revealed?' Explanation opened.':''}${o.familiar?(o.parisStory?' This task or another length of its story was encountered on another visit.':' This task was seen on an earlier visit.'):''}${o.knownFact?' A related fact appeared earlier.':''}${o.priorExposureUnknown?' Earlier fact familiarity was not recorded.':''}</p>${o.helper?`<p>Helper example: ${esc(helpers[o.nodeId]?.title||o.helper.exampleId)}. Example answers tried: ${esc(o.helper.attempts.map(v=>helpers[o.nodeId]?.choices?.[v]??v).join(', ')||'None')}. ${o.helper.revealed?'Example explanation opened. ' :''}Representation${o.helper.modelUsed?' used':' not used'}: ${o.helper.steps||0} steps currently counted${o.helper.spotlight!==null?', a detail spotlighted':''}.</p>`:''}${o.method?`<p>Answer method: ${esc({knew:'Reported knowing it',worked:'Worked it out',counted:'Counted',together:'Worked together'}[o.method]||o.method)}.</p>`:''}<p>Reading: ${o.reading==='independent'?'reported read independently':o.reading==='together'?'read together':o.reading==='listened'?'reported listened to the passage':'not observed'}.</p>${o.designChoice?`<p>Unscored design idea: ${esc(o.designChoice)}.</p>`:''}</div>`;}
export function gardenNotes(state){
 const g=ensureGarden(state);
 return `<section class="panel"><h2>Garden visits</h2><p class="tiny">This is a shared browser notebook, not separate learner profiles. English and French Paris are guided reading practice. Its notes describe individual comprehension/word-meaning tasks and reported reading support; no oral decoding accuracy, fluency, or reading level is inferred.</p><p>${g.visits.length} visit${g.visits.length===1?'':'s'} · ${g.visits.filter(v=>v.finished).length} at an ending</p><p class="tiny">Story tasks include context and guide prompts. Answer methods describe extra help, not a baseline assessment. Reading observations are reported separately. Unvisited subjects remain unknown; a project invitation does not establish completion or mastery.</p>${g.visits.length?`<div class="summary-links"><a class="secondary" href="#storm">Return to a visit</a><a href="#companions" class="text-button">Change companions</a></div>`:'<a href="#storm">Explore First Morning</a>'}</section><details class="panel"><summary>Story observations (${g.observations.length} recorded)</summary>${g.observations.map(storyEvidence).join('')||'<p>No story observations recorded yet.</p>'}</details>`;
}

export function frenchLanding(state){
 const waiting=ensureGarden(state).visits.filter(v=>v.entrance.startsWith('french-')&&!v.finished);
 return `${heading('Paris en français','Small adventures in French, one sentence at a time.')}<section class="paris-exploration-intro"><img src="./paris-scene.svg" alt="An imagined Paris skyline beside the river" width="800" height="450"><div><p class="place-name" lang="fr">Bonjour, Paris !</p><h2>Follow a French story.</h2><p>Visit the books, the river, or the rooftop garden. Each short story has two French questions. Read on your own, follow one sentence, or open English meaning and word help.</p><p>Listen with a local French voice if your device offers one. There is no timer or required score.</p><a class="secondary" href="#paris">Paris stories in English</a></div></section>${waiting.length?`<section class="resume-strip"><div><h2>Your French errands are waiting</h2>${waiting.map(v=>`<p>${esc(entranceById(v.entrance).title)} <button class="secondary" data-resume-visit="${v.id}">Continue ${esc(frenchLessons.find(l=>l.id===v.entrance).title)}</button></p>`).join('')}</div></section>`:''}<section class="paris-destinations" aria-label="French Paris errands">${frenchLessons.map(l=>`<article class="paris-destination"><span class="french-place-symbol" aria-hidden="true">${l.symbol}</span><p class="place-name">${esc(l.place)}</p><h2 lang="fr">${esc(l.title)}</h2><p>${esc(l.invitation)}</p><button class="primary" data-start-path="${l.id}">Explore ${esc(l.title)}</button></article>`).join('')}</section><details class="paris-parent-note"><summary>Grown-ups: French practice</summary><p>Three authored short-sentence stories, each with two comprehension questions. Revisit them as familiar practice. English meaning, vocabulary help, listening, and sentence focus are recorded as support. There is no French proficiency estimate or automatic difficulty adjustment. English reading suggestions use only English Paris work.</p><p>This browser has one shared notebook. French errands are labelled separately, but the app does not identify who is playing. Saving, export, and reset use the existing grown-up controls.</p></details>`;
}
